# NGINX (Layer 7) routing by path
location /api/ { proxy_pass http://api_pool; }
location /static/ { proxy_pass http://cdn_pool; }
# an L4 balancer cannot see the URL to make this choice

# BIND named.conf
view "internal" {
  match-clients { 10.0.0.0/8; };
  zone "example.com" { type primary; file "internal/example.com.zone"; };
};
view "external" {
  match-clients { any; };
  zone "example.com" { type primary; file "external/example.com.zone"; };
};

# nginx
ssl_stapling on;
ssl_stapling_verify on;
ssl_trusted_certificate /etc/ssl/chain.pem;
# verify a staple is returned
openssl s_client -connect example.com:443 -status </dev/null 2>/dev/null | grep -A2 'OCSP Response Status'

# nginx.conf
upstream app {
    server 10.0.1.20:9000;
    keepalive 64;
}
server {
    location / {
        proxy_pass http://app;
        proxy_http_version 1.1;
        proxy_set_header Connection "";
    }
}

# sysctl
net.ipv4.ip_local_port_range = 1024 65535
net.ipv4.tcp_tw_reuse = 1

// Node.js: outlive the ALB's 60 s idle timeout
const server = app.listen(8080);
server.keepAliveTimeout = 65 * 1000;
server.headersTimeout = 66 * 1000;

# confirm the ALB side
aws elbv2 describe-load-balancer-attributes --load-balancer-arn $ARN \
  --query "Attributes[?Key=='idle_timeout.timeout_seconds']"

# nginx.conf
location /ws/ {
    proxy_pass http://chat_backend;
    proxy_http_version 1.1;
    proxy_set_header Upgrade $http_upgrade;
    proxy_set_header Connection "upgrade";
    proxy_read_timeout 3600s;   # or keep pings under 60s
}

# server-side heartbeat (ws library)
setInterval(() => wss.clients.forEach(c => c.ping()), 30000);

